__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"SCAM_MESSAGES",{enumerable:!0,get:function(){return n}});const n=[{from:'USPS Delivery',channel:'SMS',text:'Your package is on hold due to an incomplete address. Pay a $1.99 redelivery fee within 24 hours: usps-parcel-help.info/pay',scam:!0,why:'USPS does not text you a link asking for money. The tiny fee is bait to get your card number, and that web address is not usps.com.'},{from:'Your bank',channel:'SMS',text:'A new device signed in to your account. If this was you, no action is needed. If not, call the number on the back of your card.',scam:!1,why:'Legit. It asks for nothing and sends you to the number printed on your own card, not a link or a number inside the message.'},{from:'Campus Jobs Board',channel:'Email',text:'You are hired as a personal assistant! $450 a week, no interview. We will mail a check. Deposit it, keep your pay, and send the rest back by Zelle.',scam:!0,why:'The fake check scam, aimed at students. The check bounces days later, and the money you "sent back" was your own. Real jobs interview you and never ask for money back.'},{from:'Grandma',channel:'SMS',text:'Hi sweetie its Grandma, I got a new phone. I am stuck at the store and my card is not working. Can you send $200 in gift cards? I will pay you back tonight.',scam:!0,why:'A new number plus an urgent request for gift cards is a classic impersonation scam. Call the number you already have for her. Nobody real needs to be paid in gift cards.'},{from:'Spotify',channel:'Email',text:'Your Premium payment did not go through. Your plan will pause at the end of the billing period. Update your payment in the app or at spotify.com.',scam:!1,why:'Legit. No panic deadline, and it points you to the official app and site that you would open yourself.'},{from:'crypto.king.trades',channel:'DM',text:'Bro I turned $200 into $9,400 in 2 weeks with a trading bot. Guaranteed 15% a week. Send $100 on Cash App and I will flip it for you tonight.',scam:!0,why:'Nobody can guarantee returns, and 15% a week is impossible to keep up. Once you send money on a payment app to a stranger, it is gone.'},{from:'Venmo',channel:'Email',text:'You paid Jordan M. $18.00 for "pizza". See this payment any time in your Venmo app under Activity.',scam:!1,why:'Legit. It is a plain receipt for something you did. It asks for nothing and has no "verify your account" link.'},{from:'IRS Refund Dept',channel:'Email',text:'You are owed a tax refund of $1,247.50. Claim within 48 hours or lose it. Confirm your Social Security number and debit card here.',scam:!0,why:'The IRS contacts people by mail, not by email with a countdown. It never asks for your Social Security number and card through a link.'},{from:'Scholarship Awards Team',channel:'Email',text:'Congratulations! You have been selected for a $5,000 scholarship. To release your award, pay the $49 processing fee today.',scam:!0,why:'Real scholarships never charge a fee to receive them. Also, you cannot win something you did not apply for.'},{from:'Netflix',channel:'Email',text:'Your plan price changes next month from $15.49 to $17.99. No action is needed. You can manage your plan any time in Account settings.',scam:!1,why:'Legit. A price notice that asks for nothing and tells you to use settings you find on your own.'},{from:'sneaker_plug_atl',channel:'DM',text:'Got those Jordans in your size, $90, way under retail. Has to be Zelle or Cash App friends and family, no PayPal. Ships tomorrow, trust me.',scam:!0,why:'Insisting on a payment with no buyer protection is the tell. Zelle and "friends and family" payments cannot be reversed when the shoes never arrive.'},{from:'Your Bank Fraud Team',channel:'SMS',text:'FRAUD ALERT: Did you spend $890.00 at BestTech? Reply YES or NO. If NO, an agent will call to help move your money to a safe account.',scam:!0,why:'The "agent" who calls is the scammer, and the "safe account" is theirs. A real bank will never ask you to move your money to protect it.'},{from:'Coach Ramirez',channel:'Email',text:'Reminder: team fees of $40 are due Friday. Pay through the school portal like last season, or bring a check to practice.',scam:!1,why:'Legit. It refers to something you already know about, uses the usual way of paying, and has no surprise link.'},{from:'Prize Center',channel:'SMS',text:'CONGRATS! You won a $500 Amazon gift card in our monthly drawing. Claim now, just cover $4.95 shipping: winbig-rewards.co',scam:!0,why:'You cannot win a drawing you never entered, and a real prize does not need a shipping fee. The $4.95 is how they get your card number.'},{from:'Game Support',channel:'DM',text:'Your account was flagged for a free 10,000 V-Bucks reward. Log in at vbucks-free-claim.net with your Epic username and password to collect.',scam:!0,why:'Free in-game currency from a link is a login trap. Type your password there and the scammer owns your account and any card saved on it.'}]},1522,[]);